{"explanation":"Use the transactional history rule directly: edits outside groups create bounded undo entries; grouped edits defer history until an outermost commit, while cancel restores the saved document. Undo/redo exchange current documents between bounded stacks and are disabled inside groups.","mapping":"The optional source rule maps alignment to preserving document snapshots and history ordering; however, astronomical interferometry is not relevant to this state-transition contract, so no outside assumptions are used.","assumptions":"Documents contain JSON-compatible object data and event values are JSON scalars as specified. State is represented by the current document, undo/redo arrays, group-start array, and configured limit.","applies":"function applies(input){return !!input&&!!input.config&&Array.isArray(input.events)&&input.config.limit>=1&&input.config.limit<=4}","holds":"function holds(input,output){if(!Array.isArray(output)||output.length!==input.events.length)return false;return output.every(x=>x&&typeof x==='object'&&Object.keys(x).sort().join(',')==='canRedo,canUndo,depth,document'&&typeof x.canRedo==='boolean'&&typeof x.canUndo==='boolean'&&Number.isInteger(x.depth))}","program":"function solve({config,state,event}){
  const cp=x=>{if(Array.isArray(x))return x.map(cp);if(x&&typeof x==='object'){let y={};for(const k of Object.keys(x))y[k]=cp(x[k]);return y}return x};
  const same=(a,b)=>{if(a===b)return true;if(typeof a!==typeof b||a===null||b===null||typeof a!=='object')return false;let ak=Object.keys(a),bk=Object.keys(b);if(ak.length!==bk.length)return false;for(const k of ak)if(!Object.prototype.hasOwnProperty.call(b,k)||!same(a[k],b[k]))return false;return true};
  const trim=(a,n)=>{while(a.length>n)a.shift()};
  let s=state?{d:cp(state.d),u:cp(state.u),r:cp(state.r),g:cp(state.g),l:state.l}: {d:cp(config.initial),u:[],r:[],g:[],l:config.limit};
  const push=(a,v)=>{a.push(cp(v));trim(a,s.l)};
  if(event.type==='begin')s.g.push(cp(s.d));
  else if(event.type==='set'||event.type==='delete'){
    let n=cp(s.d),changed=false;
    if(event.type==='set'){changed=!Object.prototype.hasOwnProperty.call(n,event.key)||!same(n[event.key],event.value);if(changed)n[event.key]=cp(event.value)}
    else if(Object.prototype.hasOwnProperty.call(n,event.key)){changed=true;delete n[event.key]}
    if(changed){if(!s.g.length){push(s.u,s.d);s.r=[]}s.d=n}
  } else if(event.type==='commit'&&s.g.length){let start=s.g.pop();if(!s.g.length&&!same(start,s.d)){push(s.u,start);s.r=[]}}
  else if(event.type==='cancel'&&s.g.length)s.d=s.g.pop();
  else if((event.type==='undo'||event.type==='redo')&&!s.g.length){let a=event.type==='undo'?s.u:s.r,b=event.type==='undo'?s.r:s.u;if(a.length){let x=a.pop();push(b,s.d);s.d=x}}
  return {state:s,output:{document:cp(s.d),canUndo:!s.g.length&&s.u.length>0,canRedo:!s.g.length&&s.r.length>0,depth:s.g.length}};
}"}
